            time_ratio: time_ratio.clamp(0.125, 8.0),
            harmony_mode: None,
            reference_voice: None,
            voice_count: None,
            voice_position: None,
            voice_leading_enabled: None,
            voice_leading_style: None,
            octave_mode: None,
            counterpoint_species: None,
            counterpoint_strictness: None,
            hold_mode: None,
        }
    }
}

impl Default for CanonVoice {
    fn default() -> Self {
        Self {
            delay_beats: 1.0,
            transpose_degrees: 0,
            time_ratio: 1.0,
            harmony_mode: None,
            reference_voice: None,
            voice_count: None,
            voice_position: None,
            voice_leading_enabled: None,
            voice_leading_style: None,
            octave_mode: None,
            counterpoint_species: None,
            counterpoint_strictness: None,
            hold_mode: None,
        }
    }
}

